package containers

import (
	"fmt"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	"github.com/charmbracelet/bubbles/table"
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The logs pane used to live here — a viewState, a viewport, soft wrap, ANSI
// stripping, scroll keys, reload, follow, a timestamps toggle and an external
// pager. None of it was specific to containers except the last three, and those
// are properties of where the text came from rather than of the pane, so the
// whole thing moved into the document viewer and the three became a Source's
// optional capabilities (see sources.go). `l` and `i` now emit one message and
// this view goes back to being a table.

// Model represents the containers view state
type Model struct {
	config         *config.Config
	showAll        bool
	containerTable datatable.Model[docker.Container]
	spinner        spinner.Model
	loading        bool
	// footer is the one line of transient state below the viewport (Rule 128).
	footer       sharedcomponents.FooterMessage
	confirmModal *sharedcomponents.ConfirmModal
	// choiceModal is K's Stop / Restart / Cancel. Separate from confirmModal
	// because the two answer different messages, and one field holding either
	// would make the handler guess which question was asked.
	choiceModal *sharedcomponents.ChoiceModal
	// pendingAction is the confirm modal's routing key, and only that.
	//
	// It used to be two fields in one: the routing key ("confirm-delete",
	// "confirm-prune") that handleConfirmYes reads, and a sentence for the user
	// ("Stopping web") that nothing ever rendered. Carrying both is why nobody
	// noticed the second had no reader — the field was plainly in use. What the
	// user is told now comes from the table's busy set.
	pendingAction string
	// pruning is the one action that belongs to no row: it acts on the whole
	// list, so marking every row would say something false. It gets a footer
	// line of its own instead.
	pruning       bool
	width, height int
}

// Messages

// RefreshTickMsg triggers periodic refresh
type RefreshTickMsg time.Time

// ContainersListMsg contains fetched containers
type ContainersListMsg struct {
	Containers []docker.Container
	Err        error
}

// ContainerMetricsMsg contains fetched metrics
type ContainerMetricsMsg struct {
	Metrics map[string]docker.Container
	Err     error
}

// ContainerActionMsg signals result of a container action (stop, restart, remove).
//
// ID used to be the container's *name*: every command filled it from its `name`
// argument. Nothing caught it because the only reader was a log line, where a
// name reads perfectly well. It matters now — the busy marker is keyed on the
// ID, so a message carrying a name would never lift it and the row would spin
// for the life of the view.
type ContainerActionMsg struct {
	Action string
	ID     string
	Name   string
	Err    error
}

// ContainerPruneMsg signals result of a container prune operation
type ContainerPruneMsg struct {
	Output string
	Err    error
}

// PagerExitMsg signals return from a pager (less) or shell process
type PagerExitMsg struct {
	Err error
}

// ShellWindowOpenedMsg signals the result of launching a shell in a new terminal window
type ShellWindowOpenedMsg struct {
	Err error
}

// columnStatus indexes containerColumns. Only the ones something else refers to
// are named; the sort cycle walks them by position.
const (
	columnStatus = iota
	columnName
	columnImage
)

// statusColumnWidth is the state glyph and nothing else. It carries no title —
// the icons say what they are — and it must not sort: `datatable` reserves two
// cells beyond MinWidth for any column with a comparator, to hold its arrow,
// which is expensive for a glyph.
const statusColumnWidth = 3

// containerColumns describes the containers table.
//
// The state has a column of its own (§3.22). It used to be an icon prefixed to
// the Image cell, which is why that column had to search `Image + State` to
// compensate for the icon not being where it belonged; the search still matches
// both, because a container is looked for by either.
//
// That column is also where a running action shows its spinner. The two are one
// glyph deliberately: a row answers "what is this" and "what is happening to
// it" in the same place, and `datatable` owns the precedence — busy wins.
func containerColumns() []datatable.Column[docker.Container] {
	// Metrics only mean anything while the container runs: docker reports the
	// last values it saw for the rest, which is why they read "-" rather than a
	// number that stopped being true when the container did.
	running := func(c docker.Container) bool { return c.State == "running" }
	transfer := func(io func(docker.Container) string, bytes func(docker.Container) int64) func(docker.Container) string {
		return func(c docker.Container) string {
			if !running(c) || io(c) == "" {
				return "-"
			}
			return formatNetBytes(bytes(c))
		}
	}
	netIO := func(c docker.Container) string { return c.NetIO }
	blockIO := func(c docker.Container) string { return c.BlockIO }
	byInt64 := func(get func(docker.Container) int64) func(a, b docker.Container) bool {
		return func(a, b docker.Container) bool { return get(a) < get(b) }
	}

	return []datatable.Column[docker.Container]{
		{
			Title: "", MinWidth: statusColumnWidth,
			Cell:  func(c docker.Container) string { return stateIcon(c.State) },
			Style: containerStateStyle,
		},
		{
			Title: "Name", MinWidth: 14, Flex: 2,
			Cell:   func(c docker.Container) string { return c.Name },
			Less:   func(a, b docker.Container) bool { return strings.ToLower(a.Name) < strings.ToLower(b.Name) },
			Search: func(c docker.Container) string { return c.Name },
		},
		{
			Title: "Image", MinWidth: 20, Flex: 3,
			Cell:   func(c docker.Container) string { return c.Image },
			Less:   func(a, b docker.Container) bool { return strings.ToLower(a.Image) < strings.ToLower(b.Image) },
			Search: func(c docker.Container) string { return c.Image + " " + c.State },
		},
		{
			Title: "CPU", MinWidth: 8,
			Cell: func(c docker.Container) string {
				if !running(c) {
					return "-"
				}
				return fmt.Sprintf("%.1f%%", c.CPUPercent)
			},
			Less: func(a, b docker.Container) bool { return a.CPUPercent < b.CPUPercent },
		},
		{
			Title: "Mem", MinWidth: 12,
			Cell: func(c docker.Container) string {
				if !running(c) {
					return "-"
				}
				return formatMemUsage(c.MemUsage)
			},
			Less: func(a, b docker.Container) bool { return a.MemPercent < b.MemPercent },
		},
		{
			Title: "Net RX", MinWidth: 9,
			Cell: transfer(netIO, func(c docker.Container) int64 { return c.NetRX }),
			Less: byInt64(func(c docker.Container) int64 { return c.NetRX }),
		},
		{
			Title: "Net TX", MinWidth: 9,
			Cell: transfer(netIO, func(c docker.Container) int64 { return c.NetTX }),
			Less: byInt64(func(c docker.Container) int64 { return c.NetTX }),
		},
		{
			Title: "Block RX", MinWidth: 10,
			Cell: transfer(blockIO, func(c docker.Container) int64 { return c.BlockRX }),
			Less: byInt64(func(c docker.Container) int64 { return c.BlockRX }),
		},
		{
			Title: "Block TX", MinWidth: 10,
			Cell: transfer(blockIO, func(c docker.Container) int64 { return c.BlockTX }),
			Less: byInt64(func(c docker.Container) int64 { return c.BlockTX }),
		},
		{
			Title: "Created", MinWidth: 12,
			Cell: func(c docker.Container) string { return relativeTime(c.CreatedAt) },
			// CreatedAt is compared as the string docker printed, so a value
			// that will not parse sorts after every timestamp rather than
			// silently becoming the zero time and leading the list.
			Less: func(a, b docker.Container) bool { return a.CreatedAt < b.CreatedAt },
		},
		{
			Title: "Ports", MinWidth: 16, Flex: 2,
			Cell: func(c docker.Container) string { return c.Ports },
		},
	}
}

// containerStateStyle colours the status column by the state its glyph shows.
//
// A running container is left in the default text colour rather than painted
// green. Almost every row is running, so colouring them would put a colour on
// the whole table and a signal on none of it — the colour is here to pick out
// the containers that stopped, or that are on their way somewhere.
func containerStateStyle(c docker.Container) lipgloss.Style {
	switch c.State {
	case "exited", "dead":
		return theme.StatusErrorStyle
	case "paused":
		return theme.StatusWarningStyle
	case "created", "restarting":
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	default:
		// Aucune opinion : c'est la table qui pose la couleur de texte du thème.
		return lipgloss.NewStyle()
	}
}

// containerSelectedStyles paints the selected row as an error when the
// container is not coming back on its own. It is the whole of what
// refreshSelectionStyle used to do, minus its replay of filter-then-sort to
// find out what the cursor was on.
func containerSelectedStyles(c docker.Container) table.Styles {
	if c.State == "exited" || c.State == "dead" {
		return theme.TableStylesForState("error")
	}
	return theme.TableStylesForState("normal")
}

// New creates a new containers view
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	return Model{
		config:  cfg,
		spinner: s,
		containerTable: datatable.New(datatable.Config[docker.Container]{
			Columns: containerColumns(),
			// Explicit rather than left at the zero value, which would open the
			// list Z→A and disagree with the status view (D9).
			SortColumn:     columnName,
			SelectedStyles: containerSelectedStyles,
			// The ID rather than the name: an action is issued against the ID,
			// and two containers can carry the same name across a recreate.
			Key:          func(c docker.Container) string { return c.ID },
			StatusColumn: columnStatus,
		}),
		loading: true,
	}
}

package netdiag

import (
	"fmt"
	"log"
	"strings"
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	dockerpkg "github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// portsTickMsg triggers a data refresh cycle.
type portsTickMsg struct{}

// portsDataMsg carries the result of a RunSS call.
type portsDataMsg struct {
	ports []dockerpkg.PortInfo
	err   error
}

// portsKillResultMsg carries the result of a KillProcess call.
type portsKillResultMsg struct {
	pid string
	err error
}

// portsSpinnerTickMsg turns the frame of a row a kill is running on.
//
// This model has no spinner of its own, and its data tick is two seconds apart
// — a frame that advanced on that would look stopped, which is the impression
// the whole thing exists to remove. So the kill starts a tick of its own and it
// stops itself when nothing is left running.
type portsSpinnerTickMsg struct{}

func portsSpinnerCmd() tea.Cmd {
	return tea.Tick(spinner.Dot.FPS, func(time.Time) tea.Msg { return portsSpinnerTickMsg{} })
}

// defaultPortsRefresh is what the interval falls back to. A non-positive one —
// a hand-edited 0 in the config — would make tea.Tick fire without pausing and
// spin a docker exec per frame, so it is refused here rather than trusted.
const defaultPortsRefresh = 2 * time.Second

func portsTickCmd(every time.Duration) tea.Cmd {
	if every <= 0 {
		every = defaultPortsRefresh
	}
	return tea.Tick(every, func(time.Time) tea.Msg {
		return portsTickMsg{}
	})
}

func fetchPortsCmd(image string, numeric bool) tea.Cmd {
	return func() tea.Msg {
		ports, err := dockerpkg.RunSS(image, numeric)
		return portsDataMsg{ports: ports, err: err}
	}
}

func killProcessCmd(image, pid string) tea.Cmd {
	return func() tea.Msg {
		err := dockerpkg.KillProcess(image, pid)
		return portsKillResultMsg{pid: pid, err: err}
	}
}

// statusLine is what the Ports tab derives on every frame. Pausing is a state
// rather than an event, so it is rendered from pm.paused instead of set as a
// message — a message would expire after three seconds while still paused.
func (pm *PortsModel) statusLine() components.Status {
	// Staleness outranks the pause: a pause is what the user asked for, an
	// unreachable Docker is not, and only one of the two makes the rows lie.
	if pm.stale {
		return components.Status{Text: pm.staleLabel(), Level: components.LevelError}
	}
	if pm.paused {
		return components.Status{Text: "Paused — press space to resume"}
	}
	return components.Status{}
}

// staleLabel dates the rows on screen, or says there are none to date.
func (pm *PortsModel) staleLabel() string {
	if pm.lastOK.IsZero() {
		return "Docker unreachable — no ports could be read"
	}
	return "Docker unreachable — ports as of " + theme.TimeAgo(pm.lastOK)
}

// filterTokenProto and filterTokenState are the label constants for FilterBar tokens.
const (
	filterTokenTCP     = "tcp"
	filterTokenUDP     = "udp"
	filterTokenListen  = "LISTEN"
	filterTokenEstab   = "ESTAB"
	filterTokenPaused  = "⏸ PAUSED"
	filterTokenNumeric = "numeric"
)

// PortsModel manages the real-time port monitoring sub-view.
type PortsModel struct {
	image string
	// refresh is how often the table re-reads ss. The spinner tick is separate
	// and much faster: a frame advancing on this interval would look stopped,
	// which is the impression the whole tab exists to remove.
	refresh time.Duration
	width   int
	height  int

	// The table holds the entries, filters them and keeps the cursor. The
	// tableReady / lastTableWidth / lastTableHeight trio that used to live here
	// existed only to avoid recreating the table on every two-second tick and
	// losing the scroll position; SetItems guarantees that instead.
	table datatable.Model[dockerpkg.PortInfo]

	paused bool

	// address display
	numericAddrs bool // true = raw IPs/ports (-n flag), false = DNS names

	// confirmModal guards the kill. It is the only action in the application
	// that reaches a process outside it, so it is the one that most needed a
	// confirmation and had none.
	confirmModal *components.ConfirmModal

	// lastOK is when the table last received real data, and stale says the most
	// recent fetch failed.
	//
	// They exist because a failed fetch keeps the rows: dropping them would
	// flash the table empty on a transient hiccup, two seconds apart, and the
	// rows are not wrong — they are dated. What was missing is their age. A
	// footer *message* cannot carry it either: it expires after three seconds
	// (Rule 128), and what was left was a table refreshing into failure with
	// nothing on screen saying so. That is D20's shape — "we could not look"
	// rendered as data.
	lastOK time.Time
	stale  bool

	// footer is this tab's own message line. Each tab keeps one: a shared
	// instance would let a message set on Ports outlive the switch away from it.
	footer components.FooterMessage
}

// portsColumns describes the ports table. Every column is searchable: the query
// used to run against all six joined, and it still does.
// portsColumnState is where a running kill puts its spinner.
const portsColumnState = 1

func portsColumns() []datatable.Column[dockerpkg.PortInfo] {
	text := func(get func(dockerpkg.PortInfo) string) datatable.Column[dockerpkg.PortInfo] {
		return datatable.Column[dockerpkg.PortInfo]{Cell: get, Search: get}
	}
	proto := text(func(p dockerpkg.PortInfo) string { return p.Protocol })
	state := text(func(p dockerpkg.PortInfo) string { return p.State })
	local := text(func(p dockerpkg.PortInfo) string { return p.LocalAddr })
	peer := text(func(p dockerpkg.PortInfo) string { return p.PeerAddr })
	pid := text(func(p dockerpkg.PortInfo) string { return p.PID })
	process := text(func(p dockerpkg.PortInfo) string { return p.Process })

	proto.Title, proto.MinWidth = "Proto", 6
	state.Title, state.MinWidth = "State", 10
	state.Style = portStateStyle
	local.Title, local.MinWidth = "Local Address", 26
	peer.Title, peer.MinWidth = "Peer Address", 26
	pid.Title, pid.MinWidth = "PID", 7
	process.Title, process.MinWidth, process.Flex = "Process", 10, 1

	return []datatable.Column[dockerpkg.PortInfo]{proto, state, local, peer, pid, process}
}

// portStateStyle colours the socket state, which is the column this table is
// scanned down: a listening port is something the machine offers, an
// established one is a conversation in progress, and everything else is a
// socket on its way out.
func portStateStyle(p dockerpkg.PortInfo) lipgloss.Style {
	switch strings.ToUpper(p.State) {
	case "LISTEN":
		return theme.StatusOKStyle
	case "ESTAB", "ESTABLISHED":
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	case "":
		return theme.DimStyle
	default: // TIME-WAIT, CLOSE-WAIT, SYN-SENT — transient, and not the point
		return theme.DimStyle
	}
}

// matchPortTokens applies the toggle filters: OR within a group, AND between
// them. `numeric` and `paused` are shown in the bar but filter nothing — they
// report a mode, which is why they are not consulted here.
func matchPortTokens(p dockerpkg.PortInfo, active map[string]bool) bool {
	return matchesActive(p.Protocol, active, filterTokenTCP, filterTokenUDP) &&
		matchesActive(p.State, active, filterTokenListen, filterTokenEstab)
}

// matchesActive reports whether value equals one of the labels the user turned
// on. A group with nothing on does not filter: that is "no opinion", not
// "match nothing", and getting the two confused would empty the table on open.
func matchesActive(value string, active map[string]bool, labels ...string) bool {
	anyOn := false
	for _, label := range labels {
		if !active[label] {
			continue
		}
		anyOn = true
		if strings.EqualFold(value, label) {
			return true
		}
	}
	return !anyOn
}

// newPortsModel creates a new PortsModel.
func newPortsModel(image string, refresh time.Duration) *PortsModel {
	return &PortsModel{
		image:        image,
		refresh:      refresh,
		numericAddrs: true,
		table: datatable.New(datatable.Config[dockerpkg.PortInfo]{
			Columns:    portsColumns(),
			SortColumn: -1, // the order ss reports is the order shown
			Tokens: []components.FilterToken{
				{Label: filterTokenTCP},
				{Label: filterTokenUDP},
				{Label: filterTokenListen},
				{Label: filterTokenEstab},
				{Label: filterTokenNumeric},
				{Label: filterTokenPaused},
			},
			TokenMatch: matchPortTokens,
			// A PID, not a socket: killing a process takes every socket it
			// holds, so every one of its rows spins together — which is what
			// actually happens.
			Key: func(p dockerpkg.PortInfo) string { return p.PID },
			// The State cell, being exactly what the signal is about to change.
			StatusColumn: portsColumnState,
		}),
	}
}

// initPorts returns the initial commands: an immediate fetch + the first tick.
func (pm *PortsModel) initPorts() tea.Cmd {
	return tea.Batch(fetchPortsCmd(pm.image, pm.numericAddrs), portsTickCmd(pm.refresh))
}

// InEditMode returns true when the search input or the kill confirmation has
// the keyboard.
func (pm *PortsModel) InEditMode() bool {
	return pm.table.InEditMode() || pm.confirmModal != nil
}

// resize updates terminal dimensions and lays the table out (Rule 116).
func (pm *PortsModel) resize(width, height int) {
	pm.width = width
	pm.height = height
	if width == 0 {
		return
	}
	// pm.height IS the viewport content height sent by the app (Rule 124); the
	// filter bar is rendered in the footer, outside the viewport.
	pm.table.Resize(width, max(height, 3))
}

func (pm *PortsModel) update(msg tea.Msg) (*PortsModel, tea.Cmd) {
	switch msg := msg.(type) {
	case portsTickMsg:
		return pm.handleTick()
	case portsDataMsg:
		return pm.handleData(msg)
	case portsKillResultMsg:
		return pm.handleKillResult(msg)
	case portsSpinnerTickMsg:
		return pm.handleSpinnerTick()
	case components.ConfirmModalYesMsg:
		pm.confirmModal = nil
		return pm.killSelected()
	case components.ConfirmModalNoMsg:
		pm.confirmModal = nil
		return pm, nil
	case tea.KeyMsg:
		return pm.handleKey(msg)
	}
	return pm, nil
}

// handleSpinnerTick advances the frame and schedules the next one, or lets the
// tick die when the last kill has landed.
func (pm *PortsModel) handleSpinnerTick() (*PortsModel, tea.Cmd) {
	if len(pm.table.BusyLabels()) == 0 {
		return pm, nil
	}
	pm.table.AdvanceSpinner()
	return pm, portsSpinnerCmd()
}

func (pm *PortsModel) handleTick() (*PortsModel, tea.Cmd) {
	if pm.paused {
		return pm, portsTickCmd(pm.refresh)
	}
	return pm, tea.Batch(fetchPortsCmd(pm.image, pm.numericAddrs), portsTickCmd(pm.refresh))
}

func (pm *PortsModel) handleData(msg portsDataMsg) (*PortsModel, tea.Cmd) {
	if msg.err != nil {
		log.Printf("ERROR [netdiag/ports] RunSS: %v", msg.err)
		// The rows stay: they are dated, not wrong, and the status line is what
		// says so. No footer message — this is a state, and a state that
		// expires after three seconds is how a dead table came to look alive.
		pm.stale = true
		return pm, nil
	}
	pm.stale = false
	pm.lastOK = time.Now()
	// The cursor and the scroll survive this, which is what the whole
	// tableReady dance existed to achieve on a two-second tick.
	pm.table.SetItems(msg.ports)
	return pm, nil
}

func (pm *PortsModel) handleKillResult(msg portsKillResultMsg) (*PortsModel, tea.Cmd) {
	// On every outcome: a kill that failed has to let the socket state show
	// again rather than go on turning.
	pm.table.ClearBusy(msg.pid)
	if msg.err != nil {
		log.Printf("ERROR [netdiag/ports] KillProcess pid=%s: %v", msg.pid, msg.err)
		return pm, pm.footer.Error(fmt.Sprintf("Failed to kill PID %s", msg.pid))
	}
	return pm, pm.footer.Info(fmt.Sprintf("Process %s terminated", msg.pid))
}

func (pm *PortsModel) handleKey(msg tea.KeyMsg) (*PortsModel, tea.Cmd) {
	if pm.confirmModal != nil {
		var cmd tea.Cmd
		pm.confirmModal, cmd = pm.confirmModal.Update(msg)
		return pm, cmd
	}
	if pm.table.InEditMode() {
		cmd := pm.table.Update(msg)
		pm.table.GotoTop() // a narrowing query starts from the first match
		return pm, cmd
	}
	return pm.handleKeyNormal(msg)
}

// toggleToken flips a filter and returns to the top, since the list under the
// cursor is not the list the user was looking at any more.
func (pm *PortsModel) toggleToken(label string) {
	pm.table.SetTokenActive(label, !pm.table.IsTokenActive(label))
	pm.table.GotoTop()
}

func (pm *PortsModel) handleKeyNormal(msg tea.KeyMsg) (*PortsModel, tea.Cmd) {
	switch msg.String() {
	case "up", "down", "pgup", "pgdown", "home", "end", "/":
		return pm, pm.table.Update(msg)
	case " ":
		pm.paused = !pm.paused
		pm.table.SetTokenActive(filterTokenPaused, pm.paused)
		// Pausing is a state, not an event: it is derived in statusLine rather
		// than set as a message, which would expire while still paused.
	case "t":
		pm.toggleToken(filterTokenTCP)
	case "u":
		pm.toggleToken(filterTokenUDP)
	case "l":
		pm.toggleToken(filterTokenListen)
	case "e":
		pm.toggleToken(filterTokenEstab)
	case "n":
		pm.numericAddrs = !pm.numericAddrs
		pm.table.SetTokenActive(filterTokenNumeric, pm.numericAddrs)
		return pm, fetchPortsCmd(pm.image, pm.numericAddrs)
	case "z":
		for _, label := range []string{
			filterTokenTCP, filterTokenUDP, filterTokenListen, filterTokenEstab, filterTokenPaused,
		} {
			pm.table.SetTokenActive(label, false)
		}
		pm.table.FilterBar().ClearSearch()
		pm.table.SetItems(pm.table.Items()) // re-apply with the query gone
		pm.paused = false
		pm.table.GotoTop()
	case keymap.Kill:
		return pm.confirmKill()
	}
	return pm, nil
}

// confirmKill asks before sending the signal.
//
// This is the one action in the application that reaches outside it: not a
// container to be brought back up, but a process belonging to whoever is at
// this machine, killed with SIGKILL so it gets no chance to save anything. It
// had no confirmation at all, while deleting a container — recreatable from its
// image — had one (§3.26).
func (pm *PortsModel) confirmKill() (*PortsModel, tea.Cmd) {
	entry, ok := pm.table.Selected()
	if !ok {
		return pm, nil
	}
	if entry.PID == "" {
		return pm, pm.footer.Warn("No PID available for this entry")
	}
	if pm.table.IsBusy(entry.PID) {
		return pm, pm.footer.Warn("Already killing PID " + entry.PID)
	}
	pm.confirmModal = components.NewConfirmModal(
		"Kill Process",
		fmt.Sprintf("Send SIGKILL to %s (PID %s)?\n\nThe process gets no chance to shut down cleanly.",
			entry.Process, entry.PID),
	)
	return pm, nil
}

// killSelected sends the signal, once confirmed.
func (pm *PortsModel) killSelected() (*PortsModel, tea.Cmd) {
	entry, ok := pm.table.Selected()
	if !ok {
		return pm, nil
	}
	if entry.PID == "" || pm.table.IsBusy(entry.PID) {
		return pm, nil
	}
	// Keyed on the PID, so every socket the process holds spins at once — which
	// is what happens: the kill takes them all. The State cell is the one to
	// spend, being exactly what the signal is about to change.
	pm.table.MarkBusy(entry.PID, "Killing "+entry.Process+" ("+entry.PID+")")
	return pm, tea.Batch(killProcessCmd(pm.image, entry.PID), portsSpinnerCmd())
}

func (pm *PortsModel) view() string {
	w := max(pm.width-2, 30)
	var lines []string

	// Table or empty state. When a filter is active, always render the table —
	// an empty result with no explanation reads as "no ports" rather than as
	// "your filter matched none".
	if len(pm.table.Visible()) == 0 && !pm.table.FilterBar().IsVisible() {
		lines = append(lines, theme.EmptyLineBg(w))
		msg := "No active ports found"
		switch {
		case pm.stale:
			// The status line already dates the failure; the body must not
			// claim the host has no open ports when nothing could be read.
			msg = "No ports could be read"
		case pm.table.Items() == nil:
			msg = "Loading ports..."
		}
		lines = append(lines, theme.PadWithBg(theme.Bg("  ")+theme.DimStyle.Render(msg), w))
	} else {
		lines = append(lines, pm.table.View())
	}

	return strings.Join(lines, "\n")
}

package containers

import (
	"fmt"
	"strings"

