	m := feed(t, rawModel(t), testutil.Key("r"), testutil.Key("p"))

	got := names(m)
	if len(got) != 2 || got[0] != "cache" || got[1] != "web" {
		t.Errorf("visible = %v, want the running and the paused container", got)
	}
}

