// fifth state to select alongside four real ones.
func matchContainerTokens(c docker.Container, active map[string]bool) bool {
	token := stateToken(c.State)
	anyOn := false
	for _, label := range stateTokens {
		if !active[label] {
			continue
		}
		anyOn = true
		if token == label {
